------------ import ------------
local KTool = CS.Engine.Lib.KTool
local ActivityPtUtils = import('Game.UI.FightReady.UIActivityPt.ActivityPtUtils')
local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
local GroceryUtils = import('Game.Grocery.GroceryUtils')
local UIModule = CS.Engine.UI.UIModule
local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数
------------ import ------------

---@class UIActivityPtShopNode     
                       
local UIActivityPtShopNode = Class('UIActivityPtShopNode')

function UIActivityPtShopNode:__init()
    self._shopData = {}
end

function UIActivityPtShopNode:__delete()
    self._shopData = {}
end

function UIActivityPtShopNode:Awake()
end

function UIActivityPtShopNode:Refresh(activityUuid)
    self._curUuid = checkNumber(activityUuid)

    self:InitData()
    self:FillSelf()

    self:StartTimeDown()
end

function UIActivityPtShopNode:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, CountDownTime, false, true)
end

function UIActivityPtShopNode:InitData()
    local t = ActivityPtComponent:GetShopData()
    self._shopData = checkTable(t.products)
end

function UIActivityPtShopNode:FillSelf()
    self:FillShopInfo()
    self:FillTime()
end

function UIActivityPtShopNode:FillTime()
    local t = ActivityPtComponent:GetShopData()
    local time = checkNumber(t.remainingTimes)
    CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
end

function UIActivityPtShopNode:FillShopInfo()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(table.count(self._shopData), Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
    else
        self.ScrollView:SetListItemCount(table.count(self._shopData))
    end
end

function UIActivityPtShopNode:OnGetListItemByIndex(go)
end

function UIActivityPtShopNode:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return nil
    end
    local data = self._shopData[index + 1]

    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIActivityPt.ActivityPtShopDialog.UIActivityPtShopCellNode")
    if scr then
        scr:Refresh(data, function()
            local isLocked = GroceryUtils.ProductIsLocked(data)
            if isLocked then
                GameUtils.Toast(localize("商品未解锁"))
                return
            end

            self._curInd = index + 1
            local t = {}
            for k, v in pairs(data.prices) do
                table.insert(t, {
                    current = v.current, 
                    original = v.original,
                    currency = k
                })
            end
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
                goodsId        = data.icon,
                goodsNum       = data.num,
                prices         = t,
                coinPrices     = data.coinPrices,
                maxBuyNum      = data.currentStock,
                rewards        = data.rewards,
                remainTime     = data.refreshTime,
                endTime        = data.nextRefreshLeftSeconds,
                refreshType    = data.refreshType,
                buyCb          = function (price, buyNum)
                    self:OnBuyItem(data.productId, price, buyNum, scr)
                end
            }})
        end)
    end
end

function UIActivityPtShopNode:OnBuyItem(productId, price, buyNum, scr)
    local requestPath = Interfaces.StoreActivityBuy

    local activityData = ActivityPtUtils.GetActivityData(self._curUuid)
    local data = {
        productId = productId,
        num       = buyNum,
        activityUuid = self._curUuid,
        activityType = activityData.type
    }
    data.currency = price.currency
    GameUtils.Request(requestPath, data, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then
                local consume = {}

                table.insert(consume, { ["num"] = -price.current * buyNum;
                                        ["goodsId"] = price.currency; })
                GoodsUtils.DrawRewards(consume)
                GoodsUtils.DrawRewards(responseData.rewards)

                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
                
                if self._shopData[self._curInd] then
                    self._shopData[self._curInd].currentStock = checkNumber(self._shopData[self._curInd].currentStock) - buyNum
                end

                if scr then
                    scr:RefreshData(self._shopData[self._curInd])
                end
            end
        end
    end, function(errStr)
        if string.isEmpty(errStr) or errStr == nil then
            return
        end
        printError("store buy" .. errStr)
    end)
end


function UIActivityPtShopNode:OnClick()
    if not self._cb then
        return
    end
    self._cb()
end

function UIActivityPtShopNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityPtShopNode
